using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.Runtime.InteropServices;
public static class P6StaticShadowsV2 {
 static byte[] Pixels(Bitmap b){var d=b.LockBits(new Rectangle(0,0,b.Width,b.Height),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);var p=new byte[Math.Abs(d.Stride)*b.Height];Marshal.Copy(d.Scan0,p,0,p.Length);b.UnlockBits(d);return p;}
 static double Sample(byte[] p,int w,int h,double x,double y,int c){if(x<0||y<0||x>w-1||y>h-1)return 0;int x0=(int)x,y0=(int)y,x1=Math.Min(x0+1,w-1),y1=Math.Min(y0+1,h-1);double fx=x-x0,fy=y-y0;double a=p[(y0*w+x0)*4+c]*(1-fx)+p[(y0*w+x1)*4+c]*fx,b=p[(y1*w+x0)*4+c]*(1-fx)+p[(y1*w+x1)*4+c]*fx;return a*(1-fy)+b*fy;}
 static double Alpha(byte[] p,int w,int h,double x,double y){double a=Sample(p,w,h,x,y,3);return a<16?0:a/255.0;}
 public static void Render(string rawFile,string maskFile,string output,double[] inv,double[] pins){using(var raw=new Bitmap(rawFile))using(var mask=new Bitmap(maskFile))using(var result=new Bitmap(1536,1536,PixelFormat.Format32bppArgb)){var source=Pixels(raw);var floor=Pixels(mask);var pixels=new byte[1536*1536*4];double lx=-6/Math.Sqrt(136),ly=10/Math.Sqrt(136);for(int y=0;y<1536;y++)for(int x=0;x<1536;x++){int index=(y*1536+x)*4;if(floor[index+3]<128)continue;double sx=x+0.5,sy=y+0.5,den=inv[6]*sx+inv[7]*sy+inv[8],wx=(inv[0]*sx+inv[1]*sy+inv[2])/den,wy=(inv[3]*sx+inv[4]*sy+inv[5])/den;double allA=0,blue=0,green=0,red=0;for(int i=0;i<pins.Length;i+=4){double dx=wx-pins[i],dy=wy-pins[i+1],r=pins[i+2],length=pins[i+3]*0.75,major=r*0.95+length/2,minor=r*0.95,along=dx*lx+dy*ly-length/2,across=-dx*ly+dy*lx;double uc=885.5+dx/r*312,vc=442+dy/r*312,us=885.5+across/minor*312,vs=442+along/major*312;double contact=(Math.Abs(dx)<r*1.05&&Math.Abs(dy)<r*1.05)?Alpha(source,raw.Width,raw.Height,uc,vc)*0.72:0;double cast=(Math.Abs(along)<major*1.05&&Math.Abs(across)<minor*1.05)?Alpha(source,raw.Width,raw.Height,us,vs)*0.68:0;double a=Math.Max(contact,cast);if(a==0)continue;double u=cast>contact?us:uc,v=cast>contact?vs:vc;blue=Sample(source,raw.Width,raw.Height,u,v,0)*a+blue*(1-a);green=Sample(source,raw.Width,raw.Height,u,v,1)*a+green*(1-a);red=Sample(source,raw.Width,raw.Height,u,v,2)*a+red*(1-a);allA=a+allA*(1-a);}if(allA>0){pixels[index]=(byte)Math.Round(blue/allA);pixels[index+1]=(byte)Math.Round(green/allA);pixels[index+2]=(byte)Math.Round(red/allA);pixels[index+3]=(byte)Math.Round(allA*255);}}var d=result.LockBits(new Rectangle(0,0,1536,1536),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);Marshal.Copy(pixels,0,d.Scan0,pixels.Length);result.UnlockBits(d);result.Save(output,ImageFormat.Png);}}
}
"@
